import{_ as a,o,c as s,a2 as t}from"./chunks/framework.uadeSAGW.js";const w=JSON.parse('{"title":"The shared web components say their own words","description":"","frontmatter":{"status":"accepted","date":"2026-11-14T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0031-the-shared-web-components-say-their-own-words.md","filePath":"docs/adr/0031-the-shared-web-components-say-their-own-words.md"}'),n={name:"docs/adr/0031-the-shared-web-components-say-their-own-words.md"};function r(d,e,i,l,h,c){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="the-shared-web-components-say-their-own-words" tabindex="-1">The shared web components say their own words <a class="header-anchor" href="#the-shared-web-components-say-their-own-words" aria-label="Permalink to &quot;The shared web components say their own words&quot;">​</a></h1><p>The components of <code>web/ui</code> (<a href="./0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>) used to receive every word as a prop: <code>close-label</code>, <code>show-label</code>, <code>previous-label</code>, the stepper&#39;s <code>less-label</code>. Each caller translated the same &quot;Previous page&quot; again (<code>web.json</code> held it twice, &quot;Show password&quot; three times), and a new caller could forget one and ship an unlabeled button.</p><p>Now a component that speaks for itself, such as the label of its own close, previous or clear button, says it from <code>i18n/messages/&lt;locale&gt;/ui.json</code>, the way the phones read their generated strings (<a href="./0014-text-lives-in-one-json-file-per-language-and-namespace">ADR 0014</a>). <code>web/ui/src/i18n.ts</code> imports the JSON as it is, like the website&#39;s <code>t()</code>; no generator and no Node step is added, and CI already fails a locale that lacks a message.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li>A new namespace, <code>ui</code> (ids <code>ui.&lt;camelCaseName&gt;</code>), holds only words a component says by itself. Words about a screen&#39;s content stay in <code>app</code> and <code>web</code>, and domain words (muscles, equipment, body areas) stay in <code>domain</code>, which the body map will read for its area names.</li><li>The language is the browser&#39;s when we ship it, English otherwise (<code>uiLocale</code>); <code>setUiLocale</code> switches it, and the workshop&#39;s toolbar uses it.</li><li>The label props stay as optional overrides: a caller that needs other words for one case still passes them. Callers dropping them where the default says the same is a separate change.</li><li>Text that depends on the page (a title, a field&#39;s label, a placeholder) remains a prop: the component can&#39;t know it.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep props</strong>: nothing to build, but the duplication and the forgotten label stay.</li><li><strong>Install a vue-i18n plugin</strong>: one more runtime and an app-level setup for a dozen short messages; the website already reads the JSON directly.</li><li><strong>Generate typed functions like <code>DomainText</code></strong>: worthwhile if the namespace grows past plain messages; plain lookups are enough while it has no arguments or plurals.</li></ul>',7)])])}const m=a(n,[["render",r]]);export{w as __pageData,m as default};
